// MARK: - Errors

/// Error enum for B2bi
public struct B2biErrorType: AWSErrorType, Decodable {
    @nonexhaustive
    public enum Code: Sendable {
        /// You do not have sufficient access to perform this action.
        case accessDeniedException
        /// A conflict exception is thrown when you attempt to delete a resource (such as a profile or a capability) that is being used by other resources.
        case conflictException
        /// This exception is thrown when an error occurs in the Amazon Web Services B2B Data Interchange service.
        case internalServerException(B2bi.InternalServerException)
        /// Occurs when the requested resource does not exist, or cannot be found. In some cases, the resource exists in a region other than the region specified in the API call.
        case resourceNotFoundException
        /// Occurs when the calling command attempts to exceed one of the service quotas, for example trying to create a capability when you already have the maximum number of capabilities allowed.
        case serviceQuotaExceededException(B2bi.ServiceQuotaExceededException)
        /// The request was denied due to throttling: the data speed and rendering may be limited depending on various parameters and conditions.
        case throttlingException(B2bi.ThrottlingException)
        /// Occurs when a B2BI object cannot be validated against a request from another object. This exception can be thrown during standard EDI validation or when custom validation rules fail, such as when element length constraints are violated, invalid codes are used in code list validations, or required elements are missing based on configured element requirement rules.
        case validationException
    }

    public let error: Code
    public let message: String?
    public let response: HTTPResponse?

    public init(from decoder: any Decoder) throws {
        let singleValueContainer = try decoder.singleValueContainer()
        let responseError = try singleValueContainer.decode(AWSResponseError.self)
        switch responseError.errorCode {
        case "AccessDeniedException": self.error = .accessDeniedException
        case "ConflictException": self.error = .conflictException
        case "InternalServerException":
            let context = try singleValueContainer.decode(B2bi.InternalServerException.self)
            self.error = .internalServerException(context)
        case "ResourceNotFoundException": self.error = .resourceNotFoundException
        case "ServiceQuotaExceededException":
            let context = try singleValueContainer.decode(B2bi.ServiceQuotaExceededException.self)
            self.error = .serviceQuotaExceededException(context)
        case "ThrottlingException":
            let context = try singleValueContainer.decode(B2bi.ThrottlingException.self)
            self.error = .throttlingException(context)
        case "ValidationException": self.error = .validationException
        default:
            throw responseError
        }
        self.message = responseError.message
        self.response = responseError.response
    }

    /// return error code string
    public var errorCode: String {
        switch error {
        case .accessDeniedException: "AccessDeniedException"
        case .conflictException: "ConflictException"
        case .internalServerException: "InternalServerException"
        case .resourceNotFoundException: "ResourceNotFoundException"
        case .serviceQuotaExceededException: "ServiceQuotaExceededException"
        case .throttlingException: "ThrottlingException"
        case .validationException: "ValidationException"
        }
    }
}
